from collections import deque
maze=[list(line.rstrip('\n')) for line in open('maze.txt')]
R=len(maze);C=len(maze[0])
start=(1,1)
end=(29,29)
q=deque([start]); start_set=set([start])
while q:
  r,c=q.popleft()
  for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
    nr,nc=r+dr,c+dc
    if 0<=nr<R and 0<=nc<C and maze[nr][nc]!='#' and (nr,nc) not in start_set:
      start_set.add((nr,nc)); q.append((nr,nc))
q=deque([end]); end_set=set([end])
while q:
  r,c=q.popleft()
  for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
    nr,nc=r+dr,c+dc
    if 0<=nr<R and 0<=nc<C and maze[nr][nc]!='#' and (nr,nc) not in end_set:
      end_set.add((nr,nc)); q.append((nr,nc))
print('start set',len(start_set),'end set',len(end_set),'intersection',len(start_set & end_set))
# print cells where barrier: walls but adjacent to both sets maybe? bridging candidate.
bridges=[]
for r in range(R):
  for c in range(C):
    if maze[r][c]=='#':
      # neighbor in each set
      hasA=False; hasB=False
      for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr,nc=r+dr,c+dc
        if 0<=nr<R and 0<=nc<C and maze[nr][nc]!='#':
          if (nr,nc) in start_set: hasA=True
          if (nr,nc) in end_set: hasB=True
      if hasA and hasB:
        bridges.append((r,c))
print('potential bridges',bridges[:20],len(bridges))
